<script setup lang="ts">
import { computed, ref, useId } from 'vue'
import { isTauri } from '@tauri-apps/api/core'
import AppIcon from './AppIcon.vue'
import ChoiceSelect from './ChoiceSelect.vue'
import ElementCandidate from './ElementCandidate.vue'
import { elementColor } from '../lib/model'
import { spectrumBrowser as state, loadReferences, cancelReferences, clearReferences, addReferenceElement, toggleReferenceElement, toggleReferenceSpecies } from '../lib/spectrumBrowser'
const id=useId(),input=ref<HTMLInputElement>(),adding=ref(''),error=ref('')
const symbols=computed(()=>[...new Set(state.references.map(g=>g.element))].filter(e=>!state.addedElements.includes(e)))
const sourceGroups=computed(()=>state.references.filter(g=>state.addedElements.includes(g.element)))
const units=[{value:'nm',label:'nm'},{value:'angstrom',label:'Å（×0.1 → nm）'},{value:'um',label:'μm（×1000 → nm）'}]
const enabled=(element:string)=>state.references.some(g=>g.element===element&&state.selected.includes(g.id))
function add(){const symbol=symbols.value.find(e=>e.toLowerCase()===adding.value.trim().toLowerCase());if(!symbol){error.value='请选择当前已加载库中的元素';return}addReferenceElement(symbol);adding.value='';error.value=''}
async function choose(){if(isTauri())await loadReferences(undefined,true);else input.value?.click()}
function file(event:Event){const target=event.target as HTMLInputElement,f=target.files?.[0];if(f)void loadReferences(f,true);target.value=''}
</script>
<template>
  <section class="panel reference-panel">
    <button type="button" class="reference-heading" :aria-expanded="state.referencesExpanded" :aria-controls="id" @click="state.referencesExpanded=!state.referencesExpanded"><h2>谱线位置参考</h2><span v-if="state.referencePending">加载中…</span><span v-else-if="state.referenceError" class="reference-error">加载失败</span><span v-else-if="state.configuredLoaded" class="reference-success">已加载 · {{ state.configuredCount }} 位置</span><span v-else-if="state.references.length">用户库 · {{ state.references.length }} species</span><AppIcon name="chevron" :size="14" :class="{expanded:state.referencesExpanded}" /></button>
    <div :id="id" v-show="state.referencesExpanded" class="reference-body">
      <div class="reference-actions"><button type="button" :class="['btn',{'reference-loaded':state.configuredLoaded&&!state.referencePending}]" :disabled="state.referencePending" @click="loadReferences()">{{ state.referencePending?'正在加载…':state.configuredLoaded?'已加载 · 刷新当前库':'加载当前谱线库' }}</button><button v-if="state.referencePending" type="button" class="btn" @click="cancelReferences">取消</button><button v-if="state.references.length" type="button" class="icon-btn" title="清空参考库" aria-label="清空参考库" @click="clearReferences"><AppIcon name="close" :size="14" /></button></div>
      <p v-if="state.referenceError" class="error-text" role="alert">{{ state.referenceError }}<span v-if="state.references.length">；上次成功数据保留。</span></p>
      <form v-if="state.references.length" class="add-element" @submit.prevent="add"><ElementCandidate :id="id+'-element'" v-model="adding" :symbols="symbols" :disabled="state.referencePending" :issue="error" /><button type="submit" class="btn sm" :disabled="!symbols.length">添加</button></form><p v-if="error" class="error-text" role="alert">{{ error }}</p>
      <div class="reference-elements"><div v-for="element in state.addedElements" :key="element" class="reference-element"><button type="button" :class="['element-tile',{'element-muted':!enabled(element)}]" :style="{'--el-color':elementColor(element)}" :aria-pressed="enabled(element)" :aria-label="(enabled(element)?'关闭':'启用')+'参考元素 '+element" :title="'点击启用／关闭 '+element" @click="toggleReferenceElement(element)">{{ element }}</button><div class="reference-species"><label v-for="group in state.references.filter(g=>g.element===element)" :key="group.id"><input type="checkbox" :checked="state.selected.includes(group.id)" :aria-label="'参考 '+group.label" @change="toggleReferenceSpecies(group.id)" /><span>{{ group.species }}</span><small>{{ group.count }}</small></label></div></div></div>
      <p v-if="state.spectrum?.unit==='pixel'" class="hint">pixel 轴不叠加 nm 参考。</p>
      <details><summary>用户参考 CSV／来源</summary><div class="row2"><label class="field">元素（可留空）<input v-model="state.userElement" placeholder="Fe" /></label><label class="field">species（可留空）<input v-model="state.userSpecies" placeholder="II" /></label></div><label class="field">波长列（从0开始）<input v-model="state.userColumn" inputmode="numeric" /></label><ChoiceSelect v-model="state.userUnit" label="参考波长原单位" :options="units" /><button type="button" class="btn sm" :disabled="state.referencePending" @click="choose">打开用户参考 CSV</button><input ref="input" type="file" accept=".csv" class="reference-file" aria-label="选择参考谱线CSV" @change="file" /><p class="hint">虚线仅位置，不是元素鉴定。悬停可读库原字段；无 Aki 的线仍显示。</p><p v-for="issue in state.referenceIssues" :key="issue.file" class="hint">{{ issue.file }}：{{ issue.error }}</p><div v-for="group in sourceGroups" :key="group.id" class="reference-source"><b>{{ group.label }}</b> · {{ group.source }} · {{ group.original_unit }} → nm<small>{{ group.unit_contract }}</small><small class="mono">SHA256 {{ group.sha256 }}</small></div></details>
    </div>
  </section>
</template>
<style scoped>
.reference-panel{padding:0;min-width:0}.reference-heading{width:100%;display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:17px 20px;border:0;border-radius:13px;background:transparent;color:var(--text);text-align:left}.reference-heading h2{margin:0;margin-right:auto}.reference-heading>span{font-size:11px;color:var(--muted)}.reference-heading>svg{transition:transform .18s}.reference-heading>svg.expanded{transform:rotate(90deg)}.reference-heading .reference-success{color:var(--good)}.reference-heading .reference-error{color:var(--bad)}.reference-body{padding:0 20px 18px}.reference-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.reference-loaded{color:var(--good);border-color:color-mix(in srgb,var(--good) 40%,var(--border));background:color-mix(in srgb,var(--good) 7%,var(--panel))}.reference-elements{display:flex;flex-wrap:wrap;gap:14px;margin:15px 0}.reference-element{display:flex;align-items:flex-start;gap:8px}.reference-species{display:flex;gap:6px;flex-wrap:wrap;max-width:170px}.reference-species label{display:flex;gap:4px;align-items:center;font-size:12px}.reference-species small{color:var(--muted);font-size:10px}.element-muted{--el-color:var(--muted)!important;filter:grayscale(1);background:var(--panel-soft);border-color:var(--border)}.reference-file{display:none}details{font-size:12px}summary{cursor:pointer;color:var(--accent-text)}details .field{margin-top:10px}.reference-source{margin:10px 0;overflow-wrap:anywhere;font-size:11px}.reference-source small{display:block;color:var(--muted);font-size:10px}.hint{margin:10px 0}@media(max-width:740px){.reference-heading{padding:16px}.reference-body{padding:0 16px 16px}}
</style>
